        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(10),dp(8),dp(10),dp(8));bar.setBackground(gradient(navy,Color.rgb(11,48,67),0));
        TextView nav=tv(inner?"‹":"☰",30,white);nav.setGravity(Gravity.CENTER);bar.addView(nav,new LinearLayout.LayoutParams(dp(50),dp(48)));TextView t=tv(title,18,white);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));
