        TextView h=tv("خوش آمدید",24,navy);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h,new LinearLayout.LayoutParams(-1,dp(45)));TextView hint=tv("نوع ورود خود را انتخاب کنید و وارد شوید",13,muted);content.addView(hint,new LinearLayout.LayoutParams(-1,dp(34)));
