        Button m=btn("ورود مدیر ساختمان  〉",teal),r=btn("ورود ساکن  〉",blue);content.addView(m,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(r,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));
